ALTER TABLE public.champs_categories ADD COLUMN IF NOT EXISTS usage_ia boolean NOT NULL DEFAULT false;
COMMENT ON COLUMN public.champs_categories.usage_ia IS 'Champ de style : ses options entrent dans le vocabulaire autorisé pour tags_ia.';
UPDATE public.champs_categories SET usage_ia = true WHERE cle IN ('type_de_lieu','cadre','ambiance','styles_musicaux','ambiance_de_soiree','repertoire_ceremonie','style','rendu_des_images','supports','style_de_film','style_floral','fleurs_predilection','styles_maitrises','styles_proposes','pieces_phares','style_graphique','papiers_matieres','style_de_cuisine','regimes_specifiques','animations_culinaires','type_de_service','style_de_creation','saveurs_phares','silhouettes','styles_robe','matieres_robe','particularites_robe','matieres_costume','style_bijoux','style_accessoires','styles_coiffure','style_maquillage','types_de_ceremonies','style_de_ceremonie','dimension_spirituelle','implication_proches','style_vehicule','types_de_transport_proposes','formats_de_mariage');
UPDATE public.champs_categories SET usage_ia = true WHERE cle = 'type_de_prestation' AND categorie_id IN (SELECT id FROM public.categories WHERE nom = 'Musicien & DJ');